import java.util.*;

class Solution {
    public int findInteger(int k, int digit1, int digit2) {
        int[] digits = digit1 == digit2 ? new int[]{digit1} : new int[]{Math.min(digit1, digit2), Math.max(digit1, digit2)};
        Queue<Long> q = new LinkedList<>();
        for (int d : digits) {
            if (d > 0) q.offer((long)d);
        }
        long maxVal = Integer.MAX_VALUE;
        while (!q.isEmpty()) {
            long curr = q.poll();
            if (curr > k && curr % k == 0) return (int)curr;
            for (int d : digits) {
                long nxt = curr * 10 + d;
                if (nxt <= maxVal) q.offer(nxt);
            }
        }
        return -1;
    }
}

var findInteger = function(k, digit1, digit2) {
  const digits = digit1 === digit2 ? [digit1] : [Math.min(digit1, digit2), Math.max(digit1, digit2)];
  const q = [];
  for (const d of digits) {
    if (d > 0) q.push(d);
  }
  const maxVal = 2147483647;
  let head = 0;
  while (head < q.length) {
    const curr = q[head++];
    if (curr > k && curr % k === 0) return curr;
    for (const d of digits) {
      const nxt = curr * 10 + d;
      if (nxt <= maxVal) q.push(nxt);
    }
  }
  return -1;
};
